  "<div class=\"sv-g\">特殊強化<small class=\"dim\">(パスを Lv3 にすると候補に出る・1つだけ)</small></div>": "<div class=\"sv-g\">특수 강화<small class=\"dim\">(경로를 Lv3로 만들면 후보에 나온다·1개만)</small></div>",
