  "<div class=\"sv-g\">クラス強化</div>": "<div class=\"sv-g\">클래스 강화</div>",
  "<div class=\"sv-note sp\">特殊強化: <span class=\"no-gl\">{0}</span></div>": "<div class=\"sv-note sp\">특수 강화: <span class=\"no-gl\">{0}</span></div>",
